        upgraded = 0
        for title, module_title, lessons_spec in programs:
            c = one('SELECT id FROM courses WHERE title=?', (title,))
            if not c:
                continue
            cid = c['id']
            if one('SELECT id FROM modules WHERE course_id=? AND title=?', (cid, module_title)):
                continue
            pos = one('SELECT COALESCE(MAX(position),-1)+1 n FROM modules WHERE course_id=?', (cid,))['n']
            mid = db().execute('INSERT INTO modules(course_id,title,position) VALUES (?,?,?)', (cid, module_title, pos)).lastrowid
            for idx, (lesson_title, content, quiz) in enumerate(lessons_spec):
                lid = db().execute('INSERT INTO lessons(module_id,title,content,minutes,position) VALUES (?,?,?,?,?)',
                                   (mid, lesson_title, content, 18 + idx * 7, idx)).lastrowid
                if quiz:
                    qid = db().execute('INSERT INTO quizzes(lesson_id,pass_score) VALUES (?,?)', (lid, quiz['pass_score'])).lastrowid
                    for question in quiz['questions']:
                        db().execute('INSERT INTO questions(quiz_id,text,options,correct,explanation) VALUES (?,?,?,?,?)',
                                     (qid, question['text'], json.dumps(question['options'], ensure_ascii=False), json.dumps(question['correct']), question['explanation']))
            upgraded += 1
        db().commit()
        click.echo(f'Расширены программы: {upgraded}. Повторный запуск безопасен; существующий прогресс сохранён.')

